import React, { useEffect, useState } from "react";
import { Dropdown } from "react-bootstrap";
import { useTranslation } from "react-i18next";
import { useNavigate } from "react-router-dom";
import jsondata from "../json/Quantifier_level2.json";
import arrayShuffle from "array-shuffle";
import { Button, Grid, Slider } from "@mui/material";
import { DragDropContainer, DropTarget } from "react-drag-drop-container";
import useWebSocket, { ReadyState }  from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import ReactGA from "react-ga4";
import { SendLogData } from "../config/wslog.js";

function Level2() {
  const [mainarr, setMainarr] = useState(arrayShuffle(jsondata));
  const [setno, setSetno] = useState(0);
  const [image1, setImage1] = useState();
  const [image2, setImage2] = useState();
  const [sentence1, setSentence1] = useState();
  const [sentence2, setSentence2] = useState();
  const [currwordpool, setCurrwordpool] = useState();
  const [currcorrquant, setCurrcorrquant] = useState();

  const [processedSentence1, setProcessedSentence1] = useState([]);
  const [processedSentence2, setProcessedSentence2] = useState([]);

  const { t, i18n } = useTranslation();
  const navigate = useNavigate();

  const [currfeedback, setCurrfeedback] = useState();

  const [flag1, setFlag1] = useState(false);
  const [flag2, setFlag2] = useState(false);
  const [flag3, setFlag3] = useState(false);
  const [flag4, setFlag4] = useState(false);

  const [originalSentenceWords, setOriginalSentenceWords] = useState([]);
  const [originalSentenceWords1, setOriginalSentenceWords1] = useState([]);

  const [score, setScore] = useState(0);

    const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level 2 page");

  useEffect(() => {
    if (!mainarr[setno]) {
      setFlag4(true);
      return;
    }
    const {
      sentence1,
      sentence2,
      sent_img1,
      sent_img2,
      otherwords,
      quantifiers,
    } = mainarr[setno];

    setImage1(sent_img1);
    setImage2(sent_img2);
    setSentence1(sentence1);
    setSentence2(sentence2);
    setCurrwordpool(otherwords);
    setCurrcorrquant(quantifiers);

    let newSentence1 = sentence1;
    let newSentence2 = sentence2;

    quantifiers.forEach(({ word }) => {
      const regex = new RegExp(`\\b${word}\\b`, "gi");
      newSentence1 = newSentence1.replace(regex, "_____");
      newSentence2 = newSentence2.replace(regex, "_____");
    });

    const words1 = newSentence1.split(" ");
    const words2 = newSentence2.split(" ");

    setProcessedSentence1(words1);
    setProcessedSentence2(words2);
    setOriginalSentenceWords(words1); // NEW: for checking blank positions
    setOriginalSentenceWords1(words2);
  }, [mainarr, setno]);

  const level1select = () => {
    ReactGA.event({
      action:
        "English Quantifiers | CDAC-OlabsNxtG-En-34 | Clicked on level-1 dropdown button.",
      category:
        'English CDAC-OlabsNxtG-En-34 | level-2 "level-1" dropdown button clicked',
      label:
        'English CDAC-OlabsNxtG-En-34 | level-2 "level-1" dropdown button clicked to navigate to level-1.',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-2 "level-1" dropdown button',
      "Clicked",
      'Level-2 "level-1" dropdown button clicked to navigate to level-1.'
    );

    navigate("/launchpage/englishactivity/level1");
  };

  const handleonHit = (e, i) => {
    const newArray = [...processedSentence1];
    newArray[i] = e.dragData;
    setProcessedSentence1(newArray);
  };

  // Drop handler for sentence2
  const handleonHit2 = (e, i) => {
    const newArray = [...processedSentence2];
    newArray[i] = e.dragData;
    setProcessedSentence2(newArray);
  };

  const handledragstart1 = (e, id1, id2) => {
    console.log("Drag start:", id1, id2);
  };

  const handleverifybtn = () => {
    processedSentence1.forEach((word, index) => {
      const el = document.getElementById(`sent1-${index}`);
      if (!el) return;
      if (word === currcorrquant[0]?.word) {
        el.style.color = "green";
        setFlag2(true);
      } else {
        el.style.color = "red";
      }
    });

    processedSentence2.forEach((word, index) => {
      const el = document.getElementById(`sent2-${index}`);
      if (!el) return;
      if (word === currcorrquant[1]?.word) {
        el.style.color = "green";
        setFlag3(true);
      } else {
        el.style.color = "red";
      }
    });

     ReactGA.event({
      action:
        "English Quantifiers| CDAC-OlabsNxtG-En-34 | Clicked on Verify button",
      category: "English CDAC-OlabsNxtG-En-34 | level-1 Verify button clicked",
      label:
        "English CDAC-OlabsNxtG-En-34 | level-1 Verify button clicked to check the dropped words.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 "Next" button',
      "Clicked",
      'Level-1 "Next" button clicked to check the dropped words.'
    );
  };

  const handlesent1onClick = (val) => {
    setFlag1(true);
    if (val === currcorrquant[0].word) {
      setCurrfeedback(
        <>
          Correct! &nbsp; <b style={{ color: "green" }}>{val}</b> &nbsp; is a
          correct quantifier word.
        </>
      );
    } else {
      setCurrfeedback(
        <div style={{ textAlign: "center" }}>
          Incorrect! <b style={{ color: "red" }}>{val}</b> is not a valid{" "}
          quantifier word for this sentence.
          <br />
          <b>Hint:</b> {currcorrquant[0].feedback}
        </div>
      );
    }
  };

  const handlesent2onClick = (val) => {
    setFlag1(true);
    if (val === currcorrquant[1].word) {
      setCurrfeedback(
        <>
          Correct! &nbsp; <b style={{ color: "green" }}>{val}</b> &nbsp; is a
          correct quantifier word.
        </>
      );
    } else {
      setCurrfeedback(
        <div style={{ textAlign: "center" }}>
          Incorrect! <b style={{ color: "red" }}>{val}</b> is not a valid{" "}
          quantifier word for this sentence.
          <br />
          <b>Hint:</b> {currcorrquant[1].feedback}
        </div>
      );
    }
  };

  const renderSentence = (
    processedSentence,
    handleHit,
    prefix,
    handlesent1onClick
  ) =>
    processedSentence.map((item, idx) => {
      const isDroppable = currcorrquant.some(
        (q) => sentence1.includes(q.word) 
      );

      // Determine if this word originally was a blank
      const originallyBlank = originalSentenceWords[idx] === "_____";

      if (originallyBlank) {
        return (
          <DropTarget
            key={idx}
            targetKey="quantifier"
            onHit={(e) => handleHit(e, idx)}
          >
            <span
              id={`${prefix}-${idx}`}
              style={{
                display: "inline-block",
                minWidth: "60px",
                padding: "4px 8px",
                backgroundColor: "#FFF",
                border: "2px dashed #ccc",
                borderRadius: "4px",
                margin: "0 4px",
                color:"black !important" 
              }}
              onClick={() => handlesent1onClick(item)}
            >
              {item === "_____" ? "_____" : item}
            </span>
          </DropTarget>
        );
      }

      return (
        <span key={idx} style={{ margin: "0 4px" }}>
          {item}
        </span>
      );
    });

  const renderSentence1 = (processedSentence, handleHit, prefix) =>
    processedSentence.map((item, idx) => {
      const isDroppable = currcorrquant.some(
        (q) =>  sentence2.includes(q.word)
      );

      // Determine if this word originally was a blank
      const originallyBlank = originalSentenceWords1[idx] === "_____";

      if (originallyBlank) {
        return (
          <DropTarget
            key={idx}
            targetKey="quantifier"
            onHit={(e) => handleHit(e, idx)}
          >
            <span
              id={`${prefix}-${idx}`}
              style={{
                display: "inline-block",
                minWidth: "60px",
                padding: "4px 8px",
                backgroundColor: "#FFF",
                border: "2px dashed #ccc",
                borderRadius: "4px",
                margin: "0 4px",
                 color:"black !important"
              }}
              onClick={() => handlesent2onClick(item)}
            >
              {item === "_____" ? "_____" : item}
            </span>
          </DropTarget>
        );
      }

      return (
        <span key={idx} style={{ margin: "0 4px" }}>
          {item}
        </span>
      );
    });

  const handlenextbtn = () => {
    processedSentence1.forEach((ele, idx) => {
      const el = document.getElementById(`sent1-${idx}`);
      if (el) {
        el.style.color = "black";
      }
    });
  
    processedSentence2.forEach((ele, idx) => {
      const el = document.getElementById(`sent2-${idx}`);
      if (el) {
        el.style.color = "black";
      }
    });

    setSetno(setno + 1);
    setScore(score + 1);
    setFlag1(false);
    setFlag2(false);
    setFlag3(false);

     ReactGA.event({
       action:
         "English Quantifiers | CDAC-OlabsNxtG-En-34 | Clicked on Next button",
       category: "English CDAC-OlabsNxtG-En-34 | level-2 Next button clicked",
       label:
         "English CDAC-OlabsNxtG-En-34 | level-2 Next button clicked for next set of sentence.",
     });

     SendLogData(
       sendJsonMessage,
       pageName,
       'Level-2 "Next" button',
       "Clicked",
       'Level-2 "Next" button clicked for next set of sentence.'
     );
  };

  const handleskipbtn = () => {
    setSetno(setno + 1);
    setFlag1(false);
    setFlag2(false);
    setFlag3(false);

     ReactGA.event({
        action:
          "English Quantifiers | CDAC-OlabsNxtG-En-34 | Clicked on Skip button",
        category: "English CDAC-OlabsNxtG-En-34 | level-2 Skip button clicked",
        label:
          "English CDAC-OlabsNxtG-En-34 | level-2 Skip button clicked to skip current set of sentence.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-2 "Skip" button',
        "Clicked",
        'Level-2 "Skip" button clicked to skip current set of sentence.'
      );
  };

  const restartbtn = () => {
    ReactGA.event({
      action:
        'English Quantifiers | CDAC-OlabsNxtG-En-34 | Clicked on "Restart" button',
      category: 'English CDAC-OlabsNxtG-En-34 | "Restart" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-34 | "Restart" button clicked and level 2 restarted.',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      '"Restart" button',
      "Clicked",
      '"Restart" button clicked and level 2 restarted.'
    );

    window.location.reload();
  };

  return (
    <div
      className="scrollbar-primary row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        {flag4 ? (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
              position: "relative",
            }}
          >
            <div className="row-md-auto d-flex text-center">
              <div className="col text-center">
                <h5 style={{ marginTop: "1vh" }}>
                  <b>{t("level_2_title")}</b>
                </h5>
              </div>
              <div className="d-flex justify-content-end">
                <Dropdown className="d-flex justify-content-end">
                  <Dropdown.Toggle variant="success" id="dropdown-basic">
                    {t("levels")}
                  </Dropdown.Toggle>

                  <Dropdown.Menu>
                    <Dropdown.Item onClick={level1select}>
                      {t("level_1")}
                    </Dropdown.Item>
                    <Dropdown.Item href="#/action-1" disabled="true">
                      {t("level_2")}
                    </Dropdown.Item>
                  </Dropdown.Menu>
                </Dropdown>
              </div>
            </div>

            <div
              className="d-flex justify-content-center align-items-center"
              style={{ minHeight: "50vh" }}
            >
              <div
                className="col-sm-6 text-center "
                style={{
                  boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                  padding: "7vh 4vh 7vh 4vh",
                  backgroundColor: "#EDF6FA",
                }}
              >
                <p style={{ fontWeight: "bolder" }}>
                  You have scored {score} out of {mainarr.length} sentences.
                </p>
                <div>
                  <Button variant="contained" onClick={restartbtn}>
                   {t("restart")}
                  </Button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
              position: "relative",
            }}
          >
            <div className="row-md-auto d-flex text-center">
              <div className="col text-center">
                <h5 style={{ marginTop: "1vh" }}>
                  <b>{t("level_2_title")}</b>
                </h5>
              </div>
              <div className="d-flex justify-content-end">
                <Dropdown className="d-flex justify-content-end">
                  <Dropdown.Toggle variant="success" id="dropdown-basic">
                    {t("levels")}
                  </Dropdown.Toggle>

                  <Dropdown.Menu>
                    <Dropdown.Item onClick={level1select}>
                      {t("level_1")}
                    </Dropdown.Item>
                    <Dropdown.Item href="#/action-1" disabled="true">
                      {t("level_2")}
                    </Dropdown.Item>
                  </Dropdown.Menu>
                </Dropdown>
              </div>
            </div>

            <div
              className="d-flex align-items-center"
              style={{ marginTop: "7%" }}
            >
              <span className="me-3">Sentences</span>
              <Slider
                defaultValue={1}
                step={1}
                min={0}
                max={mainarr.length}
                value={setno + 1}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />
              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "60px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  fontSize: "16px",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {setno + 1}/{mainarr.length}
              </span>
            </div>

            <div className="row mb-4">
              <div className="col-12 col-md-6 mb-3 mb-md-0">
                <div
                  style={{
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                  }}
                >
                  {image1 && (
                    <img
                      src={require(`../Images/${image1}`)}
                      alt=""
                      style={{ maxWidth: "100%", height: "auto" }}
                    />
                  )}
                </div>
                <div
                  className="text-center mt-2"
                  style={{
                    boxShadow: "0px 4px 7px #00000029",
                    background: "#EDF6FA",
                    padding: "8px",
                    maxWidth: "100%",
                    overflowWrap: "break-word",
                    wordWrap: "break-word",
                    whiteSpace: "normal",
                    display: "flex",
                    flexWrap: "wrap",
                    justifyContent: "center",
                  }}
                >
                  {renderSentence(
                    processedSentence1,
                    handleonHit,
                    "sent1",
                    handlesent1onClick
                  )}
                </div>
              </div>
              <div className="col-12 col-md-6">
                <div
                  style={{
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                  }}
                >
                  {image2 && (
                    <img
                      src={require(`../Images/${image2}`)}
                      alt=""
                      style={{ maxWidth: "100%", height: "auto" }}
                    />
                  )}
                </div>
                <div
                  className="text-center mt-2"
                  style={{
                    boxShadow: "0px 4px 7px #00000029",
                    background: "#EDF6FA",
                    padding: "8px",
                    maxWidth: "100%",
                    overflowWrap: "break-word",
                    wordWrap: "break-word",
                    whiteSpace: "normal",
                    display: "flex",
                    flexWrap: "wrap",
                    justifyContent: "center",
                  }}
                >
                  {renderSentence1(
                    processedSentence2,
                    handleonHit2,
                    "sent2",
                    handlesent2onClick
                  )}
                </div>
              </div>
            </div>

            <div
              style={{
                marginTop: "3vh",
                boxShadow: "0px 4px 7px #00000029",
                background: "#EDF6FA",
              }}
            >
              <div style={{ textAlign: "start", paddingTop: "2vh" }}>
                <span style={{ paddingLeft: "5vh" }}>
                  Quantifiers Repository
                </span>
              </div>
              <Grid
                container
                spacing={2}
                className="justify-content-center"
                style={{ padding: "1rem" }}
              >
                {currwordpool &&
                  currwordpool.map((item, index) => (
                    <Grid item key={index} xs={6} sm={4} md={3} lg={2}>
                      <DragDropContainer targetKey="quantifier" dragData={item}>
                        <Button
                          key={index}
                          onDragStart={(e) => {
                            handledragstart1(e, item, index);
                          }}
                          style={{
                            backgroundColor: "#F5B946",
                            borderRadius: "5px",
                            textAlign: "center",
                            boxSizing: "border-box",
                            textTransform: "none",
                            color: "black",
                            width: "100%",
                            padding: "10px",
                            cursor: "grabbing",
                          }}
                        >
                          {item}
                        </Button>
                      </DragDropContainer>
                    </Grid>
                  ))}
              </Grid>
            </div>

            <div className="d-flex justify-content-around mt-3">
              <Button
                variant="contained"
                onClick={handleskipbtn}
                sx={{ backgroundColor: "#0F477E" }}
              >
                Skip
              </Button>
              <Button
                variant="contained"
                onClick={handleverifybtn}
                sx={{ backgroundColor: "#0F477E" }}
              >
                Verify
              </Button>
              <Button
                variant="contained"
                onClick={handlenextbtn}
                sx={{ backgroundColor: "#0F477E" }}
                disabled={flag2 && flag3 ? false : true}
              >
                Next
              </Button>
            </div>

            <div
              className="row justify-content-center"
              style={{ marginTop: "2vh" }}
            >
              {flag1 ? (
                <div
                  className="d-flex justify-content-center align-items-center"
                  style={{
                    width: "auto",
                    height: "auto",
                    background: "rgb(255, 255, 255)",
                    boxShadow: "rgba(0, 0, 0, 0.5) 0px 0px 10px",
                    borderRadius: "50px",
                    padding: "1rem",
                  }}
                >
                  {currfeedback}
                </div>
              ) : (
                ""
              )}
            </div>
          </div>
        )}
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "1.3rem",
              fontWeight: "bolder",
            }}
          >
            {t("instruction")}
          </div>

          <div style={{ maxHeight: "50vh", padding: "2%" }}>
            <div>
              <ul>
                <li>{t("instruction_2_1")}</li>
                <li>{t("instruction_2_2")}</li>
                <li>{t("instruction_2_3")}</li>
                <li>{t("instruction_2_4")}</li>
                <li>{t("instruction_2_5")}</li>
                <li>{t("instruction_2_6")}</li>
                <li>{t("instruction_2_7")}</li>
                <li>{t("instruction_2_8")}</li>
                <li>{t("instruction_2_9")}</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Level2;
