import { useEffect, useRef, useState } from "react";
import jsondata from "../json/Q_L1_trial2.json";
import { useTranslation } from "react-i18next";
import { Dropdown } from "react-bootstrap";
import { useNavigate } from "react-router-dom";
import {
  Button,
  Dialog,
  DialogActions,
  DialogTitle,
  Slider,
} from "@mui/material";
import info from "../Images/hint2.png";
import arrayShuffle from "array-shuffle";
import { toast, ToastContainer } from "react-toastify";
import useWebSocket from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import ReactGA from "react-ga4";
import { SendLogData } from "../config/wslog.js";

function Level1_T2() {
  const [mainarr, setMainarr] = useState(jsondata);
  const [allpara, setAllpara] = useState(
    arrayShuffle(Object.values(jsondata.data))
  );
  const [currpara, setCurrpara] = useState();
  const [allfeedback, setAllfeedback] = useState();
  const [currfeedback, setCurrfeedback] = useState();
  var [parano, setParano] = useState(0);
  const [totalpara, setTotalpara] = useState(
    Object.entries(mainarr.data).length
  );
  const [corrcountable, setCorrcountable] = useState();
  const [corruncountable, setCorruncorrcountable] = useState();
  const [corrboth, setCorrboth] = useState();

  const [selectedText, setSelectedText] = useState(null);
  const [droppedcountableTexts, setDroppedcountableTexts] = useState([]);
  const [droppeduncountableTexts, setDroppeduncountableTexts] = useState([]);
  const [droppedbothTexts, setDroppedbothTexts] = useState([]);
  const dragImageRef = useRef(null);
  var [score, setScore] = useState(0);

  const [flag, setFlag] = useState(true);
  const [flag1, setFlag1] = useState(false);
  const [flag2, setFlag2] = useState(false);
  const [flag3, setFlag3] = useState(true);

  var [open1, setOpen1] = useState(false);

  const { t, i18n } = useTranslation();
  const navigate = useNavigate();

  // const [isDraggable, setIsDraggable] = useState(false);

  const [processedPara, setProcessedPara] = useState([]);
  const [draggingElem, setDraggingElem] = useState(null);

  let details = navigator.userAgent;
  let regexp = /android|iphone|kindle|ipad/i;
  let isMobileDevice = regexp.test(details);

  console.log("isMobileDevice ==>", isMobileDevice);

  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level 1 page");

  useEffect(() => {
    if (parano >= totalpara) {
      setFlag2(true);
    } else {
      const current = allpara[parano];
      const paragraph = current.paragraph;
      const countables = current.quantifiers.countable;
      const uncountables = current.quantifiers.uncountable;
      const both = current.quantifiers.both;
      const quantifiers = current.quantifiers_feedbacks;

      setCurrpara(paragraph);
      setCorrcountable(countables);
      setCorruncorrcountable(uncountables);
      setCorrboth(both);
      setAllfeedback(quantifiers);

      // Process paragraph into word objects
      const processed = processParagraph(paragraph, quantifiers);
      setProcessedPara(processed);
    }
  }, [parano]);

  function processParagraph(paragraph, allFeedbackWords) {
    const quantifiers = allFeedbackWords.map((q) => q.word.toLowerCase());

    // Flatten paragraph into string and tokenize
    const text = paragraph.join(" ");
    const words = text.split(/\s+/); // split by spaces

    const result = [];
    let i = 0;

    while (i < words.length) {
      let found = false;

      // Try matching up to 4-word phrases, starting from longest
      for (let len = 4; len >= 1; len--) {
        const chunkWords = words.slice(i, i + len);
        const chunk = chunkWords.join(" ");
        const chunkLower = chunk.toLowerCase();
        console.log("chunkLower ==>", chunkLower);

        if (quantifiers.includes(chunkLower)) {
          result.push({
            text: chunk, // preserve original casing
            isDraggable: true,
          });
          i += len;
          found = true;
          break;
        }
      }

      if (!found) {
        result.push({
          text: words[i],
          isDraggable: false,
        });
        i++;
      }
    }

    return result;
  }

  useEffect(() => {
    const handleTouchStart = (e) => {
      const text = e.target.getAttribute("data-dragvalue");
      if (text) {
        e.dataTransfer = {
          setData: () => {}, // dummy, since mobile doesn't use it
        };
        handleDragStart(e, text);
      }
    };

    const draggables = document.querySelectorAll("[data-dragvalue]");
    draggables.forEach((el) =>
      el.addEventListener("touchstart", handleTouchStart)
    );

    return () => {
      draggables.forEach((el) =>
        el.removeEventListener("touchstart", handleTouchStart)
      );
    };
  }, [processedPara]);

  const handleDragStart = (e, val) => {
    console.log("handleDragStart called ---", val);
    e.dataTransfer.setData("text/plain", val);

    const dragImage = dragImageRef.current;
    if (dragImage) {
      dragImage.textContent = val;
      document.body.appendChild(dragImage);
      //   e.dataTransfer.setDragImage(dragImage, -10, -10);
    }
  };

  const handleTouchStart = (e) => {
    const touch = e.touches[0];
    const dragValue = e.target.getAttribute("data-dragvalue");

    if (dragValue) {
      const elem = e.target.cloneNode(true);
      elem.style.position = "absolute";
      elem.style.zIndex = 1000;
      elem.style.pointerEvents = "none";
      elem.style.left = `${touch.pageX}px`;
      elem.style.top = `${touch.pageY}px`;
      document.body.appendChild(elem);

      setDraggingElem(elem);
      setSelectedText(dragValue);
    }
  };

  const handleTouchMove = (e) => {
    if (!draggingElem) return;
    const touch = e.touches[0];

    draggingElem.style.left = `${touch.pageX}px`;
    draggingElem.style.top = `${touch.pageY}px`;
  };

  const handleTouchEnd = (e) => {
    e.preventDefault();

    if (!selectedText) return;

    // Get the drop target element under the finger
    const touch = e.changedTouches[0];
    const dropTarget = document.elementFromPoint(touch.clientX, touch.clientY);

    console.log("Dropped on: ", dropTarget);

    if (droppedcountableTexts.includes(selectedText)) {
      toast.error(
        "You have already dropped this word in this qunatifier type.",
        {
          position: "top-center",
        }
      );
    } else {
      setDroppedcountableTexts((prev) => [...prev, selectedText]);
    }

    setSelectedText("");
    if (draggingElem) {
      draggingElem.remove();
      setDraggingElem(null);
    }
  };

  const handleTouchEnd1 = (e) => {
    e.preventDefault();

    if (!selectedText) return;

    // Get the drop target element under the finger
    const touch = e.changedTouches[0];
    const dropTarget = document.elementFromPoint(touch.clientX, touch.clientY);

    console.log("Dropped on: ", dropTarget);

    if (droppedbothTexts.includes(selectedText)) {
      toast.error(
        "You have already dropped this word in this qunatifier type.",
        {
          position: "top-center",
        }
      );
    } else {
      setDroppedbothTexts((prev) => [...prev, selectedText]);
    }

    setSelectedText("");
    if (draggingElem) {
      draggingElem.remove();
      setDraggingElem(null);
    }
  };

  const handleTouchEnd2 = (e) => {
    e.preventDefault();

    if (!selectedText) return;

    // Get the drop target element under the finger
    const touch = e.changedTouches[0];
    const dropTarget = document.elementFromPoint(touch.clientX, touch.clientY);

    console.log("Dropped on: ", dropTarget);

    if (droppeduncountableTexts.includes(selectedText)) {
      toast.error(
        "You have already dropped this word in this qunatifier type.",
        {
          position: "top-center",
        }
      );
    } else {
      setDroppeduncountableTexts((prev) => [...prev, selectedText]);
    }

    setSelectedText("");
    if (draggingElem) {
      draggingElem.remove();
      setDraggingElem(null);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    const text = e.dataTransfer.getData("text/plain");
    if (droppedcountableTexts.includes(text)) {
      toast.error(
        "You have already dropped this word in this qunatifier type.",
        {
          position: "top-center",
        }
      );
    } else if (text) {
      setDroppedcountableTexts((prev) => [...prev, text]);
      setSelectedText("");
    }
  };

  const handleDrop1 = (e) => {
    e.preventDefault();
    const text = e.dataTransfer.getData("text/plain");
    if (droppeduncountableTexts.includes(text)) {
      toast.error(
        "You have already dropped this word in this qunatifier type.",
        {
          position: "top-center",
        }
      );
    } else if (text) {
      setDroppeduncountableTexts((prev) => [...prev, text]);
      setSelectedText("");
    }
  };

  const handleDrop2 = (e) => {
    e.preventDefault();
    const text = e.dataTransfer.getData("text/plain");
    if (droppedbothTexts.includes(text)) {
      toast.error(
        "You have already dropped this word in this qunatifier type.",
        {
          position: "top-center",
        }
      );
    } else if (text) {
      setDroppedbothTexts((prev) => [...prev, text]);
      setSelectedText("");
    }
  };

  const allowDrop = (e) => e.preventDefault();

  const level2select = () => {
    ReactGA.event({
      action:
        "English Quantifiers | CDAC-OlabsNxtG-En-34 | Clicked on level-2 dropdown button.",
      category:
        'English CDAC-OlabsNxtG-En-34 | level-1 "level-2" dropdown button clicked',
      label:
        'English CDAC-OlabsNxtG-En-34 | level-1 "level-2" dropdown button clicked to navigate to level-2.',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 "level-2" dropdown button',
      "Clicked",
      'Level-1 "level-2" dropdown button clicked to navigate to the level-2.'
    );

    navigate("/launchpage/englishactivity/level2");
  };

  function arraysEqual(droppedArray, correctArray, categoryPrefix) {
    const s1 = new Set(droppedArray);
    const s2 = new Set(correctArray);

    let foundwordcount = 0;

    for (const item of s1) {
      const elementId = `${categoryPrefix}-${item}`;
      const elem = document.getElementById(elementId);

      if (s2.has(item)) {
        console.log("Correct:", item);
        if (elem) elem.style.color = "green";
        foundwordcount++;
      } else {
        console.log("Incorrect:", item);
        if (elem) elem.style.color = "red";
      }
    }

    return foundwordcount === s2.size;
  }

  const handleverifybtn = () => {
    const countablecheck = arraysEqual(
      droppedcountableTexts,
      corrcountable,
      "countable"
    );
    const uncountablecheck = arraysEqual(
      droppeduncountableTexts,
      corruncountable,
      "uncountable"
    );
    const bothcheck = arraysEqual(droppedbothTexts, corrboth, "both");

    if (countablecheck && uncountablecheck && bothcheck) {
      setFlag(false);
    }

    setFlag3(false);

    ReactGA.event({
      action:
        "English Quantifiers| CDAC-OlabsNxtG-En-34 | Clicked on Verify button",
      category: "English CDAC-OlabsNxtG-En-34 | level-1 Verify button clicked",
      label:
        "English CDAC-OlabsNxtG-En-34 | level-1 Verify button clicked to check the dropped words.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 "Next" button',
      "Clicked",
      'Level-1 "Next" button clicked to check the dropped words.'
    );
  };

  const handleCountablewordonclick = (val1) => {
    if (!flag3) {
      setFlag1(true);
      if (
        corrcountable.includes(val1) &&
        allfeedback.some((item) => item.word === val1.toLowerCase())
      ) {
        setCurrfeedback(
          <>
            Correct! &nbsp; <b style={{ color: "green" }}>{val1}</b> &nbsp; is a
            correct &nbsp;<b>countable</b>&nbsp;-type quantifier word.
          </>
        );
      } else {
        setCurrfeedback(
          <div style={{ textAlign: "center" }}>
            Incorrect! <b style={{ color: "red" }}>{val1}</b> is not a valid{" "}
            <b>countable</b>-type quantifier word.
            <br />
            <b>Hint:</b> Countable words refer to items you can count.
          </div>
        );
      }
    }
  };

  const handleUncountablewordonclick = (val2) => {
    if (!flag3) {
      setFlag1(true);
      if (
        corruncountable.includes(val2) &&
        allfeedback.some((item) => item.word === val2.toLowerCase())
      ) {
        setCurrfeedback(
          <>
            Correct! &nbsp; <b style={{ color: "green" }}>{val2}</b> &nbsp; is a
            correct &nbsp;<b>uncountable</b>&nbsp;-type quantifier word.
          </>
        );
      } else {
        setCurrfeedback(
          <div style={{ textAlign: "center" }}>
            Incorrect! <b style={{ color: "red" }}>{val2}</b> is not a valid{" "}
            <b>uncountable</b>-type quantifier word.
            <br />
            <b>Hint:</b> Uncountable words cannot be counted individually.
          </div>
        );
      }
    }
  };

  const handleBothwordonclick = (val3) => {
    if (!flag3) {
      setFlag1(true);
      if (
        corrboth.includes(val3) &&
        allfeedback.some((item) => item.word === val3.toLowerCase())
      ) {
        setCurrfeedback(
          <>
            Correct! &nbsp; <b style={{ color: "green" }}>{val3}</b> &nbsp; is a
            correct &nbsp;and it is&nbsp;<b>both</b>&nbsp;-type quantifier word.
          </>
        );
      } else {
        setCurrfeedback(
          <div style={{ textAlign: "center" }}>
            Incorrect! <b style={{ color: "red" }}>{val3}</b> is not a valid{" "}
            <b>both</b>-type quantifier word.
            <br />
            <b>Hint:</b> Both quantifier words can be used as both countable and
            uncountable.
          </div>
        );
      }
    }
  };

  const handlenextbtn = () => {
    parano = parano + 1;
    setParano(parano);
    setFlag1(false);
    setFlag(true);
    setFlag3(true);

    setDroppedcountableTexts([]);
    setDroppeduncountableTexts([]);
    setDroppedbothTexts([]);

    score = score + 1;
    setScore(score);
    console.log("score ==>", score);

    ReactGA.event({
      action:
        "English Quantifiers| CDAC-OlabsNxtG-En-34 | Clicked on Next button",
      category: "English CDAC-OlabsNxtG-En-34 | level-1 Next button clicked",
      label:
        "English CDAC-OlabsNxtG-En-34 | level-1 Next button clicked for next paragraph.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 "Next" button',
      "Clicked",
      'Level-1 "Next" button for next patagraph.'
    );
  };

  const handleskipbtn = () => {
    parano = parano + 1;
    setParano(parano);
    setFlag1(false);
    setFlag(true);
    setFlag3(true);

    setDroppedcountableTexts([]);
    setDroppeduncountableTexts([]);
    setDroppedbothTexts([]);

    ReactGA.event({
      action:
        "English Quantifiers | CDAC-OlabsNxtG-En-34 | Clicked on Skip button",
      category: "English CDAC-OlabsNxtG-En-34 | level-1 Skip button clicked",
      label:
        "English CDAC-OlabsNxtG-En-34 | level-1 Skip button clicked to skip current paragraph.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 "Skip" button',
      "Clicked",
      'Level-1 "Skip" button to skip current patagraph.'
    );
  };

  const handleinfobtn = () => {
    setOpen1(true);

    ReactGA.event({
      action:
        "English Quantifiers | CDAC-OlabsNxtG-En-34 | Clicked on help icon",
      category: "English CDAC-OlabsNxtG-En-34 | level-1 help icon clicked",
      label:
        "English CDAC-OlabsNxtG-En-34 | level-1 help icon clicked for additional information of qunatifiers.",
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "Level-1 help icon",
      "Clicked",
      "Level-1 help icon clicked for additional information of qunatifiers."
    );
  };

  const handleClose = () => {
    open1 = false;
    setOpen1(open1);
  };

  const restartbtn = () => {
    ReactGA.event({
      action:
        'English Quantifiers | CDAC-OlabsNxtG-En-34 | Clicked on "Restart" button',
      category: 'English CDAC-OlabsNxtG-En-34 | "Restart" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-34 | "Restart" button clicked and level 1 restarted',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      '"Restart" button',
      "Clicked",
      '"Restart" button clicked and level 1 restarted'
    );
    window.location.reload();
  };

  return (
    <div
      className="scrollbar-primary row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        {flag2 ? (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
              position: "relative",
            }}
          >
            <div className="d-flex justify-content-between align-items-center mb-3">
              <div className="flex-grow-1 text-center">
                <h5>
                  <b>{t("level_1_title")}</b>
                </h5>
              </div>
              <Dropdown className="d-flex justify-content-end">
                <Dropdown.Toggle variant="success" id="dropdown-basic">
                  {t("levels")}
                </Dropdown.Toggle>

                <Dropdown.Menu>
                  <Dropdown.Item href="#/action-1" disabled="true">
                    {t("level_1")}
                  </Dropdown.Item>
                  <Dropdown.Item onClick={level2select}>
                    {t("level_2")}
                  </Dropdown.Item>
                </Dropdown.Menu>
              </Dropdown>
            </div>

            <div
              className="d-flex justify-content-center align-items-center"
              style={{ minHeight: "50vh" }}
            >
              <div
                className="col-sm-6 text-center "
                style={{
                  boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                  padding: "7vh 4vh 7vh 4vh",
                  backgroundColor: "#EDF6FA",
                }}
              >
                <p style={{ fontWeight: "bolder" }}>
                  You have scored {score} out of {totalpara} paragraphs.
                </p>
                <div>
                  <Button variant="contained" onClick={restartbtn}>
                      {t("restart")}
                  </Button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
              position: "relative",
            }}
          >
            <div className="row-md-auto d-flex text-center">
              <div className="col text-center">
                <h5 style={{ marginTop: "1vh" }}>
                  <b>{t("level_1_title")}</b>
                </h5>
              </div>
              <div className="d-flex justify-content-end">
                <Dropdown className="d-flex justify-content-end">
                  <Dropdown.Toggle variant="success" id="dropdown-basic">
                    {t("levels")}
                  </Dropdown.Toggle>

                  <Dropdown.Menu>
                    <Dropdown.Item href="#/action-1" disabled="true">
                      {t("level_1")}
                    </Dropdown.Item>
                    <Dropdown.Item onClick={level2select}>
                      {t("level_2")}
                    </Dropdown.Item>
                  </Dropdown.Menu>
                </Dropdown>
              </div>
            </div>

            <div
              className="d-flex align-items-center"
              style={{ marginTop: "7%" }}
            >
              <span className="me-3">Paragraph</span>
              <Slider
                defaultValue={1}
                step={1}
                min={0}
                max={totalpara}
                value={parano + 1}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />
              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "60px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  fontSize: "16px",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {parano + 1}/{totalpara}
              </span>
            </div>

            <div
              style={{
                display: "flex",
                justifyContent: "end",
                marginTop: "1vh",
              }}
            >
              <img src={info} title="Help" onClick={handleinfobtn}></img>
            </div>

            <div
              className="row-md-auto"
              style={{
                backgroundColor: "#EDF6FA",
                borderRadius: "13px",
                boxShadow: "0px 4px 7px #00000029",
                display: "flex",
                flexWrap: "wrap",
                justifyContent: "center",
                alignItems: "center",
                padding: "2%",
                paddingRight: "60px", // add space for delete icon
                marginTop: "1vh",
                textAlign: "center",
                position: "relative",
              }}
              // onMouseUp={handleMouseUp}
              // draggable={isDraggable}
              // onDragStart={handleDragStart}
              // onDragEnd={handleDragEnd}
            >
              {/* {currpara} */}
              {processedPara.map((item, idx) => (
                <span
                  key={idx}
                  style={{
                    margin: "0 4px",
                    padding: "4px",
                    cursor: item.isDraggable ? "grab" : "default",
                    backgroundColor: item.isDraggable
                      ? "#d1ecf1"
                      : "transparent",
                    border: item.isDraggable ? "1px dashed #17a2b8" : "none",
                    borderRadius: "4px",
                  }}
                  data-dragvalue={item.text}
                  draggable={!isMobileDevice && item.isDraggable}
                  onDragStart={
                    !isMobileDevice && item.isDraggable
                      ? (e) => handleDragStart(e, item.text)
                      : null
                  }
                  onTouchStart={
                    isMobileDevice && item.isDraggable
                      ? handleTouchStart
                      : undefined
                  }
                  onTouchMove={
                    isMobileDevice && item.isDraggable
                      ? handleTouchMove
                      : undefined
                  }
                >
                  {item.text}
                </span>
              ))}
            </div>

            <div
              className="container"
              style={{
                borderRadius: "13px",
                boxShadow: "0px 4px 7px #00000029",
                marginTop: "1vh",
                padding: "10px",
                background: "#EDF6FA",
                marginTop: "2vh",
              }}
            >
              <div className="row g-2">
                <div className="col-12 col-sm-4">
                  <div
                    className="text-center p-3"
                    style={{
                      borderRadius: "5px",
                      backgroundColor: "white",
                    }}
                  >
                    <span>
                      <b>Countable</b>
                    </span>
                    <div
                      onDrop={handleDrop}
                      onDragOver={allowDrop}
                      onTouchEnd={isMobileDevice ? handleTouchEnd : undefined}
                      style={{
                        minHeight: "100px",
                        padding: "10px",
                        backgroundColor: "#F7D394",
                        borderRadius: "5px",
                        boxShadow: "inset 0px 4px 7px #00000029",
                      }}
                    >
                      {droppedcountableTexts.map((text, index) => (
                        <p
                          key={index}
                          id={`countable-${text}`}
                          style={{ margin: 0 }}
                          onClick={() => handleCountablewordonclick(text)}
                          onTouchStart={() => handleCountablewordonclick(text)}
                        >
                          {text}
                        </p>
                      ))}
                    </div>
                  </div>
                </div>
                <div className="col-12 col-sm-4">
                  <div
                    className=" text-center p-3"
                    style={{
                      borderRadius: "5px",
                      backgroundColor: "white",
                    }}
                  >
                    <span>
                      <b>Both</b>
                    </span>
                    <div
                      onDrop={handleDrop2}
                      onDragOver={allowDrop}
                      onTouchEnd={isMobileDevice ? handleTouchEnd1 : undefined}
                      style={{
                        minHeight: "100px",
                        padding: "10px",
                        backgroundColor: "#F7D394",
                        borderRadius: "5px",
                        boxShadow: "inset 0px 4px 7px #00000029",
                      }}
                    >
                      {droppedbothTexts.map((text, index) => (
                        <p
                          key={index}
                          id={`both-${text}`}
                          onClick={() => handleBothwordonclick(text)}
                          onTouchStart={() => handleBothwordonclick(text)}
                          style={{ margin: 0 }}
                        >
                          {text}
                        </p>
                      ))}
                    </div>
                  </div>
                </div>
                <div className="col-12 col-sm-4">
                  <div
                    className=" text-center p-3"
                    style={{
                      borderRadius: "5px",
                      backgroundColor: "white",
                    }}
                  >
                    <span>
                      <b>Uncountable</b>
                    </span>
                    <div
                      onDrop={handleDrop1}
                      onDragOver={allowDrop}
                      onTouchEnd={isMobileDevice ? handleTouchEnd2 : undefined}
                      style={{
                        minHeight: "100px",
                        padding: "10px",
                        backgroundColor: "#F7D394",
                        borderRadius: "5px",
                        boxShadow: "inset 0px 4px 7px #00000029",
                      }}
                    >
                      {droppeduncountableTexts.map((text, index) => (
                        <p
                          key={index}
                          id={`uncountable-${text}`}
                          onClick={() => handleUncountablewordonclick(text)}
                          onTouchStart={() =>
                            handleUncountablewordonclick(text)
                          }
                          style={{ margin: 0 }}
                        >
                          {text}
                        </p>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="d-flex justify-content-around mt-4">
              <Button
                variant="contained"
                sx={{ backgroundColor: "#0F477E" }}
                onClick={handleskipbtn}
              >
                Skip
              </Button>
              <Button
                variant="contained"
                sx={{ backgroundColor: "#0F477E" }}
                onClick={handleverifybtn}
              >
                Verify
              </Button>

              <Button
                variant="contained"
                onClick={handlenextbtn}
                sx={{ backgroundColor: "#0F477E" }}
                disabled={flag}
              >
                Next
              </Button>
            </div>

            <div
              className="row justify-content-center"
              style={{ marginTop: "2vh" }}
            >
              {flag1 ? (
                <div
                  className="d-flex justify-content-center align-items-center"
                  style={{
                    width: "auto",
                    height: "auto",
                    background: "rgb(255, 255, 255)",
                    boxShadow: "rgba(0, 0, 0, 0.5) 0px 0px 10px",
                    borderRadius: "50px",
                    padding: "1rem",
                  }}
                >
                  {currfeedback}
                </div>
              ) : (
                ""
              )}
            </div>
          </div>
        )}
      </div>

      <div
        ref={dragImageRef}
        style={{
          position: "absolute",
          top: "-9999px",
          left: "-9999px",
          zIndex: "-1",
          pointerEvents: "none",
          whiteSpace: "nowrap",
        }}
      ></div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "1.3rem",
              fontWeight: "bolder",
            }}
          >
            {t("instruction")}
          </div>

          <div style={{ maxHeight: "50vh", padding: "2%" }}>
            <div>
              <ul>
                <li>{t("instruction_1_1")}</li>
                <li>{t("instruction_1_2")}</li>
                <li>{t("instruction_1_3")}</li>
                <li>{t("instruction_1_4")}</li>
                <li>{t("instruction_1_5")}</li>
                <li>{t("instruction_1_6")}</li>
                <li>{t("instruction_1_7")}</li>
                <li>{t("instruction_1_8")}</li>
                <li>{t("instruction_1_9")}</li>
                <li>{t("instruction_1_10")}</li>
              </ul>
            </div>
          </div>
        </div>
      </div>
      <ToastContainer />

      <Dialog
        open={open1}
        onClose={handleClose}
        aria-labelledby="alert-dialog-title"
        aria-describedby="alert-dialog-description"
      >
        <DialogTitle
          id="alert-dialog-title"
          style={{ backgroundColor: "#90D5FF" }}
        >
          Quantifiers meanings
        </DialogTitle>

        <table style={{ margin: "2vh", border: "1px solid black" }}>
          <tr style={{ textAlign: "center", border: "1px solid black" }}>
            <th style={{ borderRight: "1px solid black" }}>Quantifier</th>
            <th>Meaning</th>
          </tr>
          {allfeedback != null
            ? allfeedback.map((item, index) => {
                return (
                  <tr
                    key={index}
                    style={{ textAlign: "center", border: "1px solid black" }}
                  >
                    <td style={{ borderRight: "1px solid black" }}>
                      {item.word}
                    </td>
                    <td>{item.meaning}</td>
                  </tr>
                );
              })
            : ""}
        </table>
        <DialogActions>
          <Button onClick={handleClose} variant="contained">
            Ok
          </Button>
        </DialogActions>
      </Dialog>
    </div>
  );
}

export default Level1_T2;
