import { Button } from "@mui/material";
import React, { useState } from "react";
import { Card } from "react-bootstrap";
import { useTranslation } from "react-i18next";
import { useNavigate } from "react-router-dom";
import Level1 from "../Images/Level1.png";
import Level2 from "../Images/Level2.png";
import "animate.css";
import video from "../Images/verb_form.mp4";
import ReactPlayer from "react-player";
import useWebSocket from "react-use-websocket";
import ReactGA from "react-ga4";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";

function Selectlevel() {
  const { t, i18n } = useTranslation();
  const navigate = useNavigate();

  var [flag, setFlag] = useState(false);

   const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level start page");

  const handleEnded = () => {
    setTimeout(()=>setFlag(true), 2000)
  };

  const tolevel1 = () => {
    ReactGA.event({
      action:
        'English Quantifiers | CDAC-OlabsNxtG-En-34 | Clicked on "Lets Go" button',
      category: 'English CDAC-OlabsNxtG-En-34 | "Lets Go" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-34 | "Lets Go" button clicked and level 1 started',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      '"Lets Go" button',
      "Clicked",
      '"Lets Go" button clicked and level 1 started'
    );

    navigate("/launchpage/englishactivity/level1");
  };

  const tolevel2 = () => {
    ReactGA.event({
      action:
        'English Quantifiers | CDAC-OlabsNxtG-En-34 | Clicked on "Lets Go" button',
      category: 'English CDAC-OlabsNxtG-En-34 | "Lets Go" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-34 | "Lets Go" button clicked and level 2 started',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      '"Lets Go" button',
      "Clicked",
      '"Lets Go" button clicked and level 2 started'
    );

    navigate("/launchpage/englishactivity/level2");
  };
  return (
    <div className="scrollbar-primary row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
        justifyContent:"center",
        alignItems:"center"
      }}>
      {flag ? (
        <div
          className="row scrollbar-primary"
          style={{
            height: "100%",
            width: "93vw",
            overflowX: "hidden",
            overflowY: "auto",
          }}
        >
          <div className="col d-flex justify-content-center align-items-center mb-3 mt-3 animate__animated animate__bounceInLeft">
            <Card style={{ width: "18rem" }}>
              <Card.Img variant="top" src={Level1} />
              <Card.Body className="text-center">
                <Card.Title>{t("level_1_title")}</Card.Title>
                <Button variant="contained" onClick={tolevel1}>
                  {t("lets_go")}
                </Button>
              </Card.Body>
            </Card>
          </div>
          <div className="col d-flex justify-content-center align-items-center mb-3 mt-3 animate__animated animate__bounceInRight">
            <Card style={{ width: "18rem" }}>
              <Card.Img variant="top" src={Level2} />
              <Card.Body className="text-center">
                <Card.Title>{t("level_2_title")}</Card.Title>
                <Button variant="contained" onClick={tolevel2}>
                  {t("lets_go")}
                </Button>
              </Card.Body>
            </Card>
          </div>
        </div>
      ) : (
        <div
          className="row "
          style={{
            height: "90%",
            backgroundColor: "lightgray",
            position: "relative",
          }}
        >
          <ReactPlayer
            className="react-player"
            muted
            autoPlay
            url={video}
            width="100%"
            height="100%"
            controls={true}
            onEnded={handleEnded}
          />
        </div>
      )}
    </div>
  );
}

export default Selectlevel;
