import { Route, Routes, useParams } from "react-router-dom";
import "./App.css";
import HomePage from "./components/HomePage";
import Language from "./Language";
import TheoryPage from "./components/TheoryPage";
import Levelstart from "./components/Levelstart";
import AnimationPage from "./components/AnimationPage";
import Procedure from "./components/Procedure";
import MathsQuiz from "./quiz/MathsQuiz";
import Level1_parent from "./components/Level1_parent";
import Level2_parent from "./components/Level2_parent";
import { useEffect, useState } from "react";
import ReactGA from "react-ga4";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "./config/dbconfig.js";
import { browserName, browserVersion } from "react-device-detect";
import { v4 as uuid } from "uuid";
import axios from "axios";
import { useDispatch } from "react-redux";
import { useSelector } from "react-redux";
import { useTranslation } from "react-i18next";
import { changeLang } from "./store/Store.js";

function App() {
  ///////////Language integration///////////

  const { t, i18n } = useTranslation();
  const { id } = useParams();
  let dispatch = useDispatch();
  let { firstStore } = useSelector((globalState) => globalState);

  useEffect(() => {
    if (id == "en") {
      alert("in app en : ", id);
      i18n.changeLanguage("en");
      dispatch(changeLang("en"));
    }
    if (id == "hn") {
      alert("in app hn : ", id);
      i18n.changeLanguage("hn");
      dispatch(changeLang("hn"));
    }
  }, []);

  //////////////////////////////ga4//////////////////////////////

  useEffect(() => {
    ReactGA.initialize("G-ZLKNSX7SDM", {
      gaOptions: {
        gtag: true,
      },
    });
  }, []);

  /////////////////////////User Log//////////////////////////////
  const [ip, setIP] = useState("");
  const sid = uuid();

  useEffect(() => {
    localStorage.setItem("sessionid", sid);
  }, []);

  useEffect(() => {
    // to call get data function which return ip address
    getData();
  }, [ip]);

  //creating function to load ip address from the API
  const getData = async () => {
    try {
      //const res = await axios.get('https://api.ipify.org/?format=json')
      const res = await axios.get("http://10.212.8.133:8083/get_ip");
      //console.log(res.data);
      setIP(res.data.ip);
      localStorage.setItem("clientip", ip);
    } catch (error) {}
  };

  const { sendJsonMessage, readyState } = useWebSocket(logconfig.logurl, {
    onOpen: () => {
      console.log("WebSocket connection established.");
    },
    onError: () => {
      console.log("WebSocket connection Error");
    },
    share: true,
    filter: () => false,
    retryOnError: true,
    shouldReconnect: () => true,
  });

  /////////////////////////////////////////////////////////////
  return (
    <Routes>
      <Route>
        {" "}
        <Route exact path="/" element={<HomePage />}></Route>
        <Route path="/:id" element={<App />} />
        <Route exact path="/letusverify" element={<HomePage />}></Route>
        <Route exact path="/theory" element={<TheoryPage />}></Route>
        <Route exact path="/animation" element={<AnimationPage />}></Route>
        <Route exact path="/procedure" element={<Procedure />}></Route>
        <Route exact path="/quiz" element={<MathsQuiz />}></Route>
        <Route
          exact
          path="/launchpage/englishactivity"
          element={<Levelstart />}
        ></Route>
        <Route
          exact
          path="/launchpage/englishactivity/level1"
          element={<Level1_parent />}
        ></Route>
         <Route
          exact
          path="/launchpage/englishactivity/level2"
          element={<Level2_parent />}
        ></Route>
      </Route>
    </Routes>
  );
}

export default App;
